-- Import the original exercises into the existing Supabase bank.
-- Run once in the project's SQL Editor. Re-running updates these same IDs.
-- No API key or other credential belongs in this file.
BEGIN;
CREATE TABLE IF NOT EXISTS public.questoes (
  id bigint PRIMARY KEY,
  enunciado text NOT NULL,
  alternativas jsonb NOT NULL DEFAULT '[]'::jsonb,
  gabarito integer CHECK (gabarito >= 0),
  assunto text, subassunto text, instituicao text, ano integer,
  dificuldade text CHECK (dificuldade IN ('fácil','média','difícil')),
  figura_url text, resolucao text, fonte text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.questoes ADD COLUMN IF NOT EXISTS dados_aplicacao jsonb;
ALTER TABLE public.questoes ADD COLUMN IF NOT EXISTS resumo_aplicacao jsonb;
ALTER TABLE public.questoes ALTER COLUMN gabarito DROP NOT NULL;
ALTER TABLE public.questoes ENABLE ROW LEVEL SECURITY;
GRANT SELECT ON public.questoes TO authenticated;
DO $tae_policy$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public'
      AND tablename = 'questoes' AND policyname = 'authenticated users read questions') THEN
    CREATE POLICY "authenticated users read questions" ON public.questoes
      FOR SELECT TO authenticated USING (true);
  END IF;
END $tae_policy$;

DO $tae_import$
DECLARE imported integer;
BEGIN
  WITH incoming AS (
    SELECT value AS item FROM jsonb_array_elements($tae_payload$[{"id":1011001,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"Quantos subconjuntos possui o conjunto A = {12,43,56,87,99}","options":[],"answer":null,"steps":["O conjunto tem cinco elementos distintos. Para formar um subconjunto, decidimos independentemente se cada elemento entra ou não entra.","São duas escolhas para cada um dos cinco elementos: $2^5=32$. Essa contagem inclui o conjunto vazio e o próprio conjunto A."],"type":"Discursiva","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"32 subconjuntos","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":20,"number":1,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:1"},"contentVersion":"9efa9f2b982f0607"},{"id":1011002,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"Considere os conjuntos A = {1, {1} , { 2}} e B = {1, 2, { 2}} e\njulgue as afirmações a seguir.\n(i) A − B = {{1}} (ii) 2 ∈ ( B − A )\n(iii) {1} ⊂ A (iv) A ∪ B = {1, 2, {1, 2}}\n(v) B − A = { 2}\nPode-se afirmar que:","options":["Todas as proposições estão corretas","Apenas I, II, III e IV estão corretas","Apenas I, II e V estão corretas","Somente IV está incorreta","Todas as proposições estão incorretas"],"answer":3,"steps":["É necessário distinguir o número 1 do conjunto $\\{1\\}$ e o número 2 do conjunto $\\{2\\}$. Os elementos comuns a A e B são 1 e $\\{2\\}$.","Logo, $A-B=\\{\\{1\\}\\}$ e $B-A=\\{2\\}$. As afirmações I, II e V são verdadeiras.","Como $1\\in A$, o conjunto $\\{1\\}$ está contido em A: III também é verdadeira.","A união correta é $\\{1,2,\\{1\\},\\{2\\}\\}$, não $\\{1,2,\\{1,2\\}\\}$. Somente IV é falsa: alternativa D."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"D","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":20,"number":2,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:2"},"contentVersion":"9cf03d2c0e2ce2c2"},{"id":1011003,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"Em um certo concurso, 500 pessoas gabaritaram as questões de\n\nmatemática, e⁴³⁰ gabaritaram as questões de português. Se 170\n\ngabaritaram ambas, quantos gabaritaram apenas uma das duas?","options":[],"answer":null,"steps":["Das 500 pessoas que gabaritaram matemática, $500-170=330$ não gabaritaram português.","Das 430 que gabaritaram português, $430-170=260$ não gabaritaram matemática.","As duas parcelas são disjuntas: exatamente uma disciplina foi gabaritada por $330+260=590$ pessoas."],"type":"Discursiva","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"590 pessoas","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":20,"number":3,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:3"},"contentVersion":"55a919e6c42c958b"},{"id":1011004,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"Num grupo de professores, sabe-se que há 26 que lecionam para o\n\nEnsino Fundamental, 13 que lecionam para o Ensino Médio e⁵ que\n\nlecionam em ambos. Quantos professores há no grupo?","options":[],"answer":null,"steps":["Pela inclusão-exclusão, a união dos grupos tem $26+13-5=34$ professores.","Subtraímos 5 porque os professores que trabalham nos dois níveis foram contados tanto no grupo de 26 quanto no grupo de 13. O resultado pressupõe, como o enunciado pretende, que todos os professores do grupo lecionam em pelo menos um dos níveis."],"type":"Discursiva","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"34 professores","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":20,"number":4,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:4"},"contentVersion":"9f620a6df932fb5e"},{"id":1011005,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"Numa confecção há 2500 funcionários onde são fabricados três\n\ntipos de roupas: Social (S), Básica (B) e Esportiva (E). A tabela seguinte\n\nindica quantos funcionários fabricam cada tipo de roupa.\n\nTipo de roupa Funcionários\nS 1300\nB 1220\nE 1080\nS e B 220\nS e E 800\nB e E 180\nS, B e E 100\n\nQuantos funcionários fabricam SOMENTE roupas esportivas?","options":[],"answer":null,"steps":["Dos 1080 funcionários que fabricam roupas esportivas, precisamos excluir quem também fabrica roupas sociais ou básicas.","A expressão é $|E\\setminus(S\\cup B)|=|E|-|E\\cap S|-|E\\cap B|+|E\\cap S\\cap B|$.","O último termo corrige a dupla exclusão dos funcionários presentes nos três grupos: $1080-800-180+100=200$."],"type":"Discursiva","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"200 funcionários","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":21,"number":5,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:5"},"contentVersion":"b6d95fd649aee9f8"},{"id":1011006,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"Sejam A, B e C conjuntos tais que n( A∪ B ) = 8, n( A∪ C ) = 9, n\n( B∪ C ) = 10, n( A ∪ B ∪ C ) = 11 e n( A ∩ B ∩ C ) = 2.\n\nEntão, n(A) + n(B) + n(C) é igual a","options":["11","14","15","18","25"],"answer":3,"steps":["Escreva $s=|A|+|B|+|C|$ e $p=|A\\cap B|+|A\\cap C|+|B\\cap C|$. Somando as três uniões de dois conjuntos, obtemos $8+9+10=2s-p$, ou seja, $27=2s-p$.","A inclusão-exclusão na união tripla fornece $11=s-p+2$, logo $s-p=9$.","Subtraindo as equações, $s=27-9=18$. Alternativa D."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"D — 18","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":21,"number":6,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:6"},"contentVersion":"0ed139d19fe56507"},{"id":1011007,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"Enuncie os elementos de A = { x ∈ ℤ - / x > -5}","options":[],"answer":null,"steps":["Na convenção utilizada pelo livro, $\\mathbb Z_-$ representa os inteiros não positivos, incluindo o zero.","Devemos selecionar os inteiros desse conjunto estritamente maiores que −5: $-4,-3,-2,-1,0$. Portanto $A=\\{-4,-3,-2,-1,0\\}$."],"type":"Discursiva","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"A = {−4, −3, −2, −1, 0}","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":21,"number":7,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:7"},"contentVersion":"8ccdcc7366863f34"},{"id":1011008,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"Sejam x e y dois números reais não nulos e distintos entre si. Das\n\nalternativas a seguir, a única necessariamente verdadeira é:","options":["- x < y","x < x + y","y < xy","x² ≠ y²","x²- 2xy + y² > 0"],"answer":4,"steps":["A expressão da alternativa E é um quadrado perfeito: $x^2-2xy+y^2=(x-y)^2$. Como os números são distintos, $x-y\\ne0$, portanto $(x-y)^2>0$.","As demais não são necessárias: A falha para $x=-2,y=1$; B falha para $x=1,y=-1$; C falha para $x=1/2,y=1$; D falha para $x=1,y=-1$.","Logo, a única alternativa sempre verdadeira é E."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"E","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":21,"number":8,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:8"},"contentVersion":"260b2e7741c096f1"},{"id":1011009,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"Se -4<x<-1 e¹<y<2 então xy e²/x estão no intervalo:","options":["] - 8, - 1 [","] - 2, - 1/2 [","] - 2, - 1 [","] - 8, - 1/2 [","] - 1, - 1/2 ["],"answer":3,"steps":["Como $-4<x<-1$ e $1<y<2$, o produto negativo satisfaz $-8<xy<-1$. Nenhuma extremidade é atingida.","A função $2/x$ é decrescente para x negativo. Nesse intervalo, $-2<2/x<-1/2$.","O intervalo aberto que contém ambos os conjuntos de valores é $]-8,-1/2[$. Alternativa D."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"D — ]−8, −1/2[","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":22,"number":9,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:9"},"contentVersion":"4b84f663d7bdac74"},{"id":1011010,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"Escreva na ordem crescente os números:\n3 4 2 3 3 5 , , , , , ,1,2,3\n4 3 5 7 9 2\nEXÉRCÍCIOS AVANÇADOS","options":[],"answer":null,"steps":["Entre as frações menores que 1, $3/9=1/3$. Por multiplicação cruzada: $1/3<2/5$, pois $5<6$; $2/5<3/7$, pois $14<15$; e $3/7<3/4$, pois $12<21$.","Para os demais, $1<4/3<2<5/2<3$, pois $4/3=1+1/3$ e $5/2=2+1/2$.","Reunindo: $\\frac39<\\frac25<\\frac37<\\frac34<1<\\frac43<2<\\frac52<3$."],"type":"Discursiva","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"O gabarito impresso coloca 3/4 antes de 2/5 e 3/7. A ordem correta está demonstrada abaixo; os números do enunciado foram preservados.","answerText":"3/9 < 2/5 < 3/7 < 3/4 < 1 < 4/3 < 2 < 5/2 < 3","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":22,"number":10,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:10"},"contentVersion":"e01b2a8fdda55dcb"},{"id":1011011,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"Dados os conjuntos A, B e C tal que n(B ∪ C) = 20, n(A ∩ B) = 5,\n\nn(A ∩ C) = 4, n(A ∩ B ∩ C) = 1 e n(A ∪ B ∪ C) = 22 , então\n\nn[A − (B ∩ C)] é igual a:","options":["0","1","4","9","12"],"answer":3,"steps":["Os elementos que pertencem exclusivamente a A são $|A\\cup B\\cup C|-|B\\cup C|=22-20=2$.","Em $A\\cap B$ há $5-1=4$ elementos que não estão em C. Em $A\\cap C$ há $4-1=3$ que não estão em B.","Ao excluir de A os elementos de $B\\cap C$, retiramos somente a interseção tripla. Restam $2+4+3=9$ elementos: alternativa D."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"D — 9","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":23,"number":11,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:11"},"contentVersion":"5a13b02524173cc1"},{"id":1011012,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"Dado um conjunto A com n elementos indiquemos a o número de\n\nsubconjunto de A. Seja B o conjunto que se obtém acrescentando um\n\nnovo elemento a A e indiquemos por b o número de subconjuntos de B.\n\nQual a relação entre a e b ?","options":[],"answer":null,"steps":["Um conjunto com n elementos possui $a=2^n$ subconjuntos. Ao acrescentar um elemento novo, B passa a ter $n+1$ elementos e $b=2^{n+1}$ subconjuntos.","Assim, $b=2\\cdot2^n=2a$. Também podemos emparelhar cada subconjunto de A com duas escolhas em B: sem o elemento novo e com ele."],"type":"Discursiva","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"b = 2a","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":23,"number":12,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:12"},"contentVersion":"2d46f9a0cfacbe74"},{"id":1011013,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"Sejam os conjuntos A com 2 elementos, B com 3 elementos e C com\n\n4 elementos; então:","options":["A ∩ B tem no máximo 1 elemento","A ∪ C tem no máximo 5 elementos","(A ∩ B) ∩ C tem no máximo 2 elementos","(A ∪ B) ∩ C tem no máximo 2 elementos","A ∩ ∅ tem 2 elementos pelo menos"],"answer":2,"steps":["A interseção $A\\cap B\\cap C$ está contida em A. Como A tem dois elementos, essa interseção tem no máximo dois elementos. C é verdadeira.","A pode ter interseção de dois elementos com B, refutando A. A e C podem ser disjuntos, com união de seis elementos, refutando B.","A união de A e B pode conter quatro elementos de C, refutando D. A interseção de qualquer conjunto com o vazio é vazia, refutando E."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"C","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":23,"number":13,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:13"},"contentVersion":"fb449826bfd00d8b"},{"id":1011014,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"Dados dois conjuntos A e B tais que n( A ∪ B ) = 10, n( A ∩ B )= 5\n\ne n(A) > n(B), pode-se afirmar que a soma dos valores possíveis para\n\nn(A − B) é:","options":["10","11","12","13","14"],"answer":2,"steps":["Defina $a=|A-B|$ e $b=|B-A|$. A união possui dez elementos e a interseção cinco, portanto $a+b=5$.","Como $|A|=a+5>|B|=b+5$, temos $a>b$. As soluções inteiras não negativas são $(a,b)=(3,2),(4,1),(5,0)$.","Os valores possíveis de $|A-B|$ são 3, 4 e 5. A soma é $3+4+5=12$, alternativa C."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"C — 12","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":24,"number":14,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:14"},"contentVersion":"b6298e163ec01a18"},{"id":1011015,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"Num grupo de 142 pessoas foi feita uma pesquisa sobre três\n\nprogramas de televisão A, B e C e constatou-se que:\nI) 40 não assistem a nenhum dos três programas;\nII) 103 não assistem ao programa C;\nIII) 25 só assistem ao programa B;\nIV) 13 assistem aos programas A e B;\nV) o número de pessoas que assistem somente aos programas B e C é a\n\nmetade dos que assistem somente a A e B;\nVI) 25 só assistem a² programas; e\nVII) 72 só assistem a um dos programas\n\nPode-se concluir que o número de pessoas que assistem:","options":["ao programa A é 30","ao programa C é 39","aos três programas é 6","aos programas A e C é 13","aos programas A ou B é 63"],"answer":1,"steps":["A união tem $142-40=102$ pessoas. Como 72 assistem a exatamente um programa e 25 a exatamente dois, a interseção tripla tem $102-72-25=5$ pessoas.","Há $13-5=8$ pessoas exclusivamente em A e B. Exclusivamente em B e C há $8/2=4$. Exclusivamente em A e C há $25-8-4=13$.","O número de espectadores de C é diretamente $142-103=39$, provando B. Só C tem $39-4-13-5=17$ pessoas. Como só B tem 25, só A tem $72-25-17=30$.","Logo $|A|=30+8+13+5=56$, $|A\\cap C|=13+5=18$ e $|A\\cup B|=102-17=85$. Essas contas refutam as demais alternativas."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"B — 39 pessoas assistem a C","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":24,"number":15,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:15"},"contentVersion":"28a3153b767ad39e"},{"id":1011016,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"Suponhamos que, numa equipe de 10 estudantes, 6 usam óculos\n\ne⁸ usam relógio. O número de estudantes que usa, ao mesmo tempo,\n\nóculos e relógio é:","options":["exatamente 6","exatamente 2","no mínimo 6","no máximo 5","no mínimo 4"],"answer":4,"steps":["Se O é o grupo que usa óculos e R o que usa relógio, então $|O\\cap R|=6+8-|O\\cup R|$.","A união não pode exceder os dez estudantes da equipe. Assim, $|O\\cap R|\\ge6+8-10=4$. O máximo possível é 6.","A interseção pode ter 4, 5 ou 6 pessoas. Portanto a garantia correta é 'no mínimo 4', alternativa E."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"E — no mínimo 4","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":25,"number":16,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:16"},"contentVersion":"882631e56de7e9cf"},{"id":1011017,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"Se A e B são dois conjuntos tais que A ⊂ B e A ≠ φ, então:","options":["sempre existe x ∈ A tal que x ∉ B","sempre existe x ∈ B tal que x ∉ A","se x ∈ A , então x ∈ A","se x ∉ B , então x ∉ A","A ∩B = φ"],"answer":null,"steps":["Da inclusão $A\\subseteq B$, todo elemento de A também pertence a B. Pela contrapositiva, $x\\notin B\\Rightarrow x\\notin A$: D é verdadeira.","A alternativa C, tal como impressa, repete a mesma condição no antecedente e no consequente; ela também é verdadeira para qualquer conjunto A.","A é incompatível com a inclusão. B não é garantida quando a convenção do livro admite $A=B$. E é falsa, pois $A\\cap B=A\\ne\\varnothing$.","Por isso, D é o gabarito informado, mas a questão original não possui resposta única."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"O livro indica D, mas C está impressa como 'se x ∈ A, então x ∈ A', uma tautologia. O enunciado foi mantido; há mais de uma alternativa verdadeira.","answerText":"C e D são verdadeiras na impressão fornecida","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":25,"number":17,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:17"},"contentVersion":"dad33a092ce19341"},{"id":1011018,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"Sejam A = {2, 0, {0 } , 5, {5}} e B ⊂ A tais que 5 ∈ B e {0 } ∉ B . O\nnúmero de tais conjuntos B é igual a :","options":["32","16","9","8","7"],"answer":3,"steps":["A tem cinco elementos distintos: $2,0,\\{0\\},5,\\{5\\}$. O elemento 5 deve pertencer a B, e o elemento $\\{0\\}$ deve ficar de fora.","Os três elementos restantes, $2,0,\\{5\\}$, podem entrar ou não entrar livremente. Existem $2^3=8$ escolhas: alternativa D."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"D — 8","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":25,"number":18,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:18"},"contentVersion":"e45e29fdb8cc21c8"},{"id":1011019,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"Sejam A e B dois conjuntos tais que o número de subconjuntos de A\nestá compreendido entre 120 e²⁵⁰ e o número de subconjuntos não vazios\nde B é 15. Se C é um conjunto cujo número de elementos é igual à soma dos\nnúmeros de elementos de A e B então o número de partes próprias de C é :","options":["2047","2048","4094","4096","8190"],"answer":0,"steps":["Se A tem a elementos, $120<2^a<250$. A única potência de 2 nesse intervalo é $128=2^7$, logo $a=7$.","B tem quinze subconjuntos não vazios: $2^b-1=15$, portanto $b=4$. C possui $7+4=11$ elementos.","Subconjuntos próprios são todos, exceto o próprio C; o vazio é contado. Assim, o resultado é $2^{11}-1=2047$, alternativa A."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"A — 2047","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":26,"number":19,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:19"},"contentVersion":"6f1f9d9e8706a74d"},{"id":1011020,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"Numa fábrica em greve, seis operários combinaram que pelo\nmenos dois deles ficariam de vigília para evitar a entrada de outros\n\nfuncionários. O número de maneiras distintas segundo as quais a\n\nentrada da fábrica pode ser vigiada pelos operários é :","options":["64","63","58","57","56"],"answer":3,"steps":["Uma vigília é determinada pela escolha de um subconjunto dos seis operários. Existem $2^6=64$ subconjuntos.","Excluímos a escolha vazia e as seis escolhas com apenas um operário: $64-1-6=57$.","Todas as escolhas restantes têm pelo menos dois operários e são admissíveis. Alternativa D."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"D — 57","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":26,"number":20,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:20"},"contentVersion":"3ed60b455cec412a"},{"id":1011021,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"Considere os conjuntos A = {1 , {1} , 2} e B = {1 , 2 , { 2}}\ne as cinco afirmações\nI) A - B = { 1 }\nII) { 2} ⊂ ( B - A )\nIII) {1} ⊂ A\nIV) A ∪ B = { 1, 2, {1, 2} }\nV) B - A = { { 2} }\nLogo,","options":["todas as afirmações estão erradas","só existe uma afirmação correta","as afirmações ímpares estão corretas","as afirmações III e V estão corretas","as afirmações I e IV são as únicas incorretas"],"answer":3,"steps":["As diferenças são $A-B=\\{\\{1\\}\\}$ e $B-A=\\{\\{2\\}\\}$. Portanto I é falsa, pois confunde 1 com $\\{1\\}$, enquanto V é verdadeira.","II é falsa: para $\\{2\\}$ ser subconjunto de $B-A$, o número 2 teria que ser elemento de $B-A$; ali há apenas o conjunto $\\{2\\}$.","III é verdadeira, pois $1\\in A$. A união é $\\{1,2,\\{1\\},\\{2\\}\\}$, então IV é falsa.","Somente III e V estão corretas: alternativa D."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"D","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":26,"number":21,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:21"},"contentVersion":"c896f88462b0db7a"},{"id":1011022,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"Sejam $U$ o conjunto das brasileiras, $A$ o conjunto das cariocas, $B$ o conjunto das morenas e $C$ o conjunto das mulheres de olhos azuis. Qual diagrama representa as mulheres morenas ou de olhos azuis que não são cariocas, reunidas com as mulheres cariocas que não são morenas nem têm olhos azuis?","options":["Diagrama A","Diagrama B","Diagrama C","Diagrama D","Diagrama E"],"answer":1,"steps":["Mulheres morenas ou de olhos azuis que não são cariocas formam $(B\\cup C)\\setminus A$. Devemos sombrear B e C fora de A, incluindo a parte comum a B e C que está fora de A.","Mulheres cariocas que não são morenas nem têm olhos azuis formam $A\\setminus(B\\cup C)$: devemos acrescentar somente a parte exclusiva de A.","A região final é $[(B\\cup C)\\setminus A]\\cup[A\\setminus(B\\cup C)]$, representada pelo diagrama B. As interseções de A com B ou C não são sombreadas."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"B","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":27,"number":22,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:22"},"figure":{"src":"questoes-algebra-figuras/1011022.webp","width":765,"height":890,"alt":"Gráfico, diagrama ou tabela necessário para resolver a questão."},"contentVersion":"c26bbaecc012eda4"},{"id":1011023,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"Numa classe, existem 19 meninas; 10 crianças louras; 10 meninos\n\nnão louros e⁴ meninas louras. Considere então as afirmativas:\n\n(1) 6 são os meninos louros.\n\n(2) 15 são as meninas não louras.\n(3) 40 são as crianças da classe.\n(4) 25 são as crianças louras ou meninas.\n(5) 31 são as crianças não louras ou meninos.\nConclua que o número de afirmações verdadeiras é igual a:","options":["1","2","3","4","5"],"answer":3,"steps":["Das dez crianças louras, quatro são meninas; logo há seis meninos louros. Das dezenove meninas, quinze não são louras. I e II são verdadeiras.","Há $19+6+10=35$ crianças, portanto III é falsa. Louras ou meninas são $10+19-4=25$, então IV é verdadeira.","Não louras ou meninos correspondem a todas as crianças exceto as quatro meninas louras: $35-4=31$. V é verdadeira.","São quatro afirmações verdadeiras: I, II, IV e V. Alternativa D."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"D — quatro afirmações verdadeiras","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":28,"number":23,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:23"},"contentVersion":"b341b7e03b43ae6e"},{"id":1011024,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"Um grupo de 72 turistas visitou a França ou a Espanha. O número\ndos que visitaram a França é o sêxtuplo do número daqueles que\nvisitaram França e Espanha, o qual, é a terça parte dos que visitaram\n\nsó a Espanha. O número de turistas que visitou um único país é igual a :","options":["18","32","36","48","64"],"answer":4,"steps":["Seja x o número de turistas que visitaram ambos os países. Visitaram a França $6x$, portanto somente a França foram $5x$. Somente a Espanha foram $3x$.","A união totaliza $5x+x+3x=9x=72$, de onde $x=8$.","Visitaram um único país $5x+3x=8x=64$ turistas. Alternativa E."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"E — 64 turistas","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":28,"number":24,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:24"},"contentVersion":"d6b510e126fcf270"},{"id":1011025,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"Depois de n dias de férias, um estudante observa que :\n\n(1) Choveu 7 vezes, de manhã ou à tarde.\n\n(2) Quando chove de manhã não chove à tarde.\n\n(3) Houve 5 tardes sem chuva.\n\n(4) Houve 6 manhãs sem chuva.\n\nNestas condições, o valor de n é igual a :","options":["4","7","8","9","10"],"answer":3,"steps":["Em n dias existem n manhãs e n tardes. Se seis manhãs foram secas, choveu em $n-6$ manhãs. Se cinco tardes foram secas, choveu em $n-5$ tardes.","O enunciado totaliza sete ocorrências de chuva e não permite chuva de manhã e à tarde no mesmo dia. Logo $(n-6)+(n-5)=7$.","Resolvendo, $2n-11=7$, então $n=9$. São três manhãs e quatro tardes chuvosas, confirmando o total. Alternativa D."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"D — 9 dias","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":28,"number":25,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:25"},"contentVersion":"623b66a52ab24b46"},{"id":1011026,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"Os valores de x e y para os quais { x , 2y } = { x + 3 , y } são\ntais que x+ y é","options":["6","5","4","3","2"],"answer":0,"steps":["Como os conjuntos são iguais, x deve coincidir com um elemento de $\\{x+3,y\\}$. A igualdade $x=x+3$ é impossível, então $x=y$.","Substituindo, a igualdade de conjuntos é $\\{x,2x\\}=\\{x+3,x\\}$. Se $x=0$, os conjuntos seriam $\\{0\\}$ e $\\{3,0\\}$, que são diferentes.","Para $x\\ne0$, o segundo elemento deve satisfazer $2x=x+3$, logo $x=3$ e $y=3$. Conferindo: ambos os conjuntos são $\\{3,6\\}$. Assim, $x+y=6$."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"A — 6","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":29,"number":26,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:26"},"contentVersion":"be7d4472f10610aa"},{"id":1011027,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"Denotemos por n ( X ) o número de elementos de um conjunto finito\nX . Sejam A, B e C conjuntos tais que n ( A ∪ B ) = 8 , n ( A ∪ C ) = 9\n, n ( B ∪ C ) = 10 , n ( A ∪ B ∪ C ) = 11 e n ( A ∩ B ∩ C ) = 2 .Então,\nn ( A ) + n ( B ) + n ( C ) é igual a:","options":["11","14","15","18","25"],"answer":3,"steps":["Defina $s=|A|+|B|+|C|$ e $p=|A\\cap B|+|A\\cap C|+|B\\cap C|$. A soma das três uniões de pares fornece $2s-p=8+9+10=27$.","Pela inclusão-exclusão tripla, $s-p+2=11$, ou seja, $s-p=9$.","Subtraindo, obtemos $s=18$. Alternativa D."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"D — 18","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":29,"number":27,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:27"},"contentVersion":"424a0e4e843eb36b"},{"id":1011028,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"Sejam dois conjuntos, X e Y , e a operação ∆, definida por\nX ∆Y = ( X - Y ) ∪ ( Y - X ) . Pode-se afirmar que","options":["( X ∆Y ) ∩ ( X ∩ Y ) = φ","( X ∆Y ) ∩ ( X - Y ) = φ","( X ∆Y ) ∩ ( Y - X ) = φ","( X ∆Y ) ∪ ( X - Y ) = X","( X ∆Y ) ∪ ( Y - X ) = X"],"answer":0,"steps":["A diferença simétrica $X\\triangle Y$ contém exatamente os elementos que pertencem a apenas um dos conjuntos X e Y.","A interseção $X\\cap Y$ contém os elementos que pertencem aos dois. Essas condições são incompatíveis, logo $(X\\triangle Y)\\cap(X\\cap Y)=\\varnothing$.","As alternativas B e C falham quando as respectivas diferenças são não vazias. D e E não são identidades: a união com uma diferença já contida na diferença simétrica não recupera os elementos da interseção. Portanto A."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"A","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":29,"number":28,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:28"},"contentVersion":"e10dec694b4ad7e7"},{"id":1011029,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"Em relação à teoria dos conjuntos, considere as seguintes afirmativas\n\nrelacionadas aos conjuntos A, B e C:\nI. Se A ∈ B e B ⊆ C então A ∈ C.\nII. Se A ⊆ B e B ∈ C então A ∈ C.\nIII. Se A ⊆ B e B ∈ C então A ⊆ C.\nEstão corretas:","options":["nenhuma das alternativas","somente a alternativa I","somente as alternativas I e II","somente as alternativas II e III","todas as alternativas"],"answer":1,"steps":["I é verdadeira: se A é um elemento de B e todos os elementos de B também pertencem a C, então A é elemento de C.","Para refutar II e III, escolha $A=\\{1\\}$, $B=\\{1,2\\}$ e $C=\\{\\{1,2\\}\\}$. Temos $A\\subseteq B$ e $B\\in C$.","Entretanto, A não é o único elemento de C, logo $A\\notin C$; e $1\\notin C$, logo A não está contido em C. II e III são falsas. Alternativa B."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"B — somente I","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":29,"number":29,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:29"},"contentVersion":"06d658cca174b850"},{"id":1011030,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"Na cidade C, constatou-se que todas as pessoas que gostam de\n\nmúsica clássica não gostam de música sertaneja. Verificou-se, ainda,\n\nque 5% da população gostam de música clássica e de “rock”, que 10%\n\ngostam de rock e de música sertaneja; que 25% gostam de “rock”; que\n\n50% gostam de música sertaneja e que 30% gostam de música clássica.\n\nO percentual de habitantes da cidade C que não “curtem” nenhum dos\n\ngêneros musicais citados é de:","options":["10%","8%","5%","2%","0%\nCAIU NOS ÚLTIMOS CONCURSOS"],"answer":0,"steps":["Sejam C, S e R os grupos que apreciam música clássica, sertaneja e rock. Como ninguém aprecia simultaneamente clássica e sertaneja, $C\\cap S=\\varnothing$ e a interseção tripla também é vazia.","A inclusão-exclusão fornece $|C\\cup S\\cup R|=30\\%+50\\%+25\\%-5\\%-10\\%=90\\%$.","Os que não apreciam nenhum desses gêneros são o complemento: $100\\%-90\\%=10\\%$. Alternativa A."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"A — 10%","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":30,"number":30,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:30"},"contentVersion":"7f101b9aee3985ee"},{"id":1011031,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"(EPCAR 2021) Numa caixa foram guardados 302 utensílios de\n\ncozinha entre garfos e facas, nacionais e importados. Alguns desses\n\nutensílios foram confeccionados em metal e o restante em material não\n\nmetálico.\n\nSobre todos esses utensílios, afirma-se que:\n\n• 142 eram importados;\n\n• 108 eram garfos\n\n• 102 foram confeccionados em metal;\n\n• 71 eram garfos importados;\n\n• 27 eram garfos de metal;\n\n• 52 eram importados e confeccionados em metal;\n\n• 18 eram garfos importados e confeccionados em metal.\n\n• Com base nessas informações sobre esses utensílios, pode-se\n\nafirmar que","options":["O número de garfos nacionais confeccionados em material não\n\nmetálico é igual a²⁶","O número de garfos nacionais é igual ao número de facas importadas\n\nconfeccionadas em material não metálico","O número de facas nacionais confeccionadas em material não\n\nmetálico é maior que 90","O número de garfos importados confeccionados em material não\n\nmetálico é menor que 50"],"answer":1,"steps":["Sejam I os importados, G os garfos e M os metálicos. Há 18 garfos importados metálicos; garfos importados não metálicos são $71-18=53$; garfos nacionais metálicos são $27-18=9$.","Garfos nacionais não metálicos são $108-71-9=28$. Garfos nacionais, somando os dois materiais, são $108-71=37$.","Facas importadas metálicas são $52-18=34$. Facas importadas no total são $142-71=71$, portanto as importadas não metálicas são $71-34=37$. Isso prova B.","Para conferir C: há $102-27-34=41$ facas nacionais metálicas e $302-108-71=123$ facas nacionais no total; as nacionais não metálicas são $123-41=82$, não mais de 90. A e D também são falsas pelos valores 28 e 53."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"EPCAR 2021","year":2021,"solution":"Texto","solutionNote":"","answerText":"B","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":31,"number":31,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:31"},"contentVersion":"c54651d152e0d316"},{"id":1011032,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"(EPCAR 2020) Para dinamizar suas aulas no 8º ano a professora\n\nLuiza organizou um jogo distribuindo duas fichas contendo operações\n\ncom os números reais. Dois alunos participaram da 1º rodada do jogo:\n\nLucas e Mateus. Ao jogarem, esses alunos receberam as seguintes fichas:\nDepois de resolverem as operações, cada aluno deveria associas\n\ncorretamente os resultados obtidos em cada ficha a somente um dos\n\nconjuntos abaixo.\nP = ℝ - ℚ\nW = ℤ - ℤ *+\nX = ℚ*- ∩ ℝ *-\nT = ℝ - ℚ +\n\nOs resultados obtidos por Lucas e Mateus foram os seguintes:\nLucas afirmou que A ∈ T e B ∈ W\nMateus afirmou que C ∈ X e D ∈ T\n\nSe Lucas e Mateus acertaram as operações nas suas duas fichas, então","options":["Lucas e Mateus acertaram todas as correspondências entre os\n\nnúmeros calculados e os conjuntos","Mateus acertou as duas correspondências e Lucas errou a\n\ncorrespondências de um dos números A ou B","Lucas e Mateus erraram uma das correspondências cada","Lucas acertou as duas correspondências e Mateus errou a\n\ncorrespondência de um dos números C ou D"],"answer":0,"steps":["Na ficha A, $0{,}\\overline7=7/9$ e $(5/4)^0=1$. O numerador é $(7/9+2/9+1)^{-1}=1/2$. O denominador é $-1/2-4^{3/2}-2^{-1}=-9$. Logo $A=-1/18$.","Na ficha B, $8^{0{,}\\overline6}=8^{2/3}=4$, $4^{3/2}=8$, $2^{\\sqrt9}=8$ e $9^{0{,}5}=3$. O denominador é $-(1/49)^{-1/2}=-7$. Assim $B=(4+8-8+3)/(-7)=-1$.","Na ficha C, $(0{,}333\\ldots)^3=1/27$, $1\\frac45=9/5$, $2{,}2=11/5$ e $-1{,}1333\\ldots=-17/15$. Então $C=[(1/27)(9/5)+11/5]/(-17/15)=(34/15)/(-17/15)=-2$.","Na ficha D, $[(1/6)^{-3}\\cdot0{,}\\overline6]^{1/2}=\\sqrt{216\\cdot2/3}=12$ e $[(2/3)^0-1/(1{,}333\\ldots)]^{1/2}=\\sqrt{1-3/4}=1/2$. Logo $D=(12+1/2)^{-1/2}=\\sqrt2/5$.","A é racional negativo, logo pertence a $T=\\mathbb R\\setminus\\mathbb Q_+$. B é inteiro não positivo, portanto pertence a W. C é racional estritamente negativo, portanto pertence a X. D é irracional, logo também pertence a T. Todas as correspondências estão corretas: alternativa A."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"EPCAR 2020","year":2020,"solution":"Texto","solutionNote":"","answerText":"A","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":32,"number":32,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:32"},"contentVersion":"60582ef0c752c143"},{"id":1011033,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"1 {33) (CN 2021) Considere o conjunto A = { x / x = , n ∈ ℕ um\nn + 1 }\nsubconjunto da reta. É correto afirmar que:","options":["Existe um único elemento de A cuja distância a qualquer outro\n\nelemento, também de A, é inferior a qualquer real positivo","Zero é um elemento do conjunto A","Fixando qualquer valor real positivo p, sempre existirão dois\n\nelementos do conjunto A cuja distância na reta real é menor do que p","Existe um elemento do conjunto A que não é racional","Existem dois elementos do conjunto A, de tal modo que a diferença\n\nentre eles não é um número racional"],"answer":2,"steps":["Os elementos são $a_n=1/(n+1)$. Todos são racionais positivos; por isso zero não pertence a A e as alternativas B, D e E são falsas.","A distância entre termos consecutivos é $a_n-a_{n+1}=1/[(n+1)(n+2)]$. Dado $p>0$, escolha n suficientemente grande para que $(n+1)(n+2)>1/p$. Então essa distância é menor que p, provando C.","A alternativa A exigiria que um elemento estivesse a distância inferior a todo real positivo de outro elemento distinto; isso obrigaria a distância a ser zero, o que é impossível entre números distintos."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"C","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":33,"number":33,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:33"},"contentVersion":"7b09b48199546921"},{"id":1011034,"topic":"Conjuntos","sub":"Teoria dos conjuntos","difficulty":"Não classificada","text":"(CN 2020) A triste e irreparável tragédia ocorrida com o Museu\n\nNacional, situado na Quinta da Boa Vista em São Cristovão, RJ, em\n\n02/09/2018, incentivou uma pesquisa com um grupo de estudantes, com\n\no intuito de saber quais museus já visitaram. O resultado aparece a seguir:\n\n- Apenas quatro museus foram mencionados: Museu Nacional (MN),\n\nMuseu do Amanhã (MA), Centro Cultural Banco do Brasil (CCBB) e\n\nMuseu Histórico Nacional (MHN);\n\n- Todos os consultados afirmaram já terem ido ao MA, sendo que 32\n\nnunca estiveram em qualquer outro dos museus mencionados;\n\n- Dentre 50 dos estudantes que também já foram no CCBB, 30 nunca\n\nforam aos outros dois museus mencionados.\n\n- Dentre 40 estudantes que também já foram ao MN, 22 nunca foram\n\naos outros dois museus;\n\n-Dentre 30 estudantes que também já foram no MHN, 18 nunca foram\n\naos outros dois museus mencionados.\n\nCom base nessas informações, quantos estudantes ao total responderam\n\na essa pesquisa?","options":["148","136","122","117","105"],"answer":2,"steps":["Todos visitaram o Museu do Amanhã; 32 visitaram somente esse museu. Entre os outros três museus, há 30 visitantes exclusivos do CCBB, 22 exclusivos do MN e 18 exclusivos do MHN, totalizando 70.","Se t visitaram os três museus e x, y, z visitaram somente os pares CCBB–MN, CCBB–MHN e MN–MHN, então $x+y+t=50-30=20$, $x+z+t=40-22=18$ e $y+z+t=30-18=12$.","Daí $x=13-t/2$, $y=7-t/2$ e $z=5-t/2$. A não negatividade e a integridade impõem $t\\in\\{0,2,4,6,8,10\\}$.","O total de estudantes é $32+70+x+y+z+t=127-t/2$, podendo ser 127, 126, 125, 124, 123 ou 122. Dentre as opções, somente 122 aparece: alternativa C. Nesse caso, $t=10$, $x=8$, $y=2$ e $z=0$, confirmando todos os totais."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"CN 2020","year":2020,"solution":"Texto","solutionNote":"Os dados sozinhos permitem mais de um total inteiro. A alternativa C é a única opção apresentada compatível com eles; essa ressalva não altera o enunciado original.","answerText":"C — 122 estudantes, entre as alternativas apresentadas","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":34,"number":34,"chapter":"Fundamentos da teoria dos conjuntos","publicationYear":2021,"bookKey":"11:34"},"contentVersion":"29072f80689ff690"},{"id":1037001,"topic":"Equações, inequações e sistemas","sub":"Módulo de um número real","difficulty":"Não classificada","text":"Assinale com V ou F\n( ) A equação x + 5 = -3 não possui solução\n( ) A única solução da equação x - 1 = 7 é x = 8\n( ) Se a > b então - a < -b\n* 1 1( ) Se ,a b ∈ℝ + e a > b então <\na b\n( ) A equação x² - 4 = 3 possui exatamente duas soluções reais","options":[],"answer":null,"steps":["Um módulo nunca é negativo, portanto $|x+5|=-3$ não tem solução: V. Já $|x-1|=7$ implica $x-1=7$ ou $x-1=-7$, dando $x=8$ ou $x=-6$: a unicidade é F.","Multiplicar $a>b$ por −1 inverte a desigualdade, produzindo $-a<-b$: V. Para $a>b>0$, dividir por $ab>0$ dá $1/b>1/a$: V.","$|x^2-4|=3$ equivale a $x^2=7$ ou $x^2=1$. As quatro soluções $\\pm\\sqrt7,\\pm1$ refutam a afirmação de exatamente duas: F."],"type":"Discursiva","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"V–F–V–V–F","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":40,"number":1,"chapter":"Módulo de um número real","publicationYear":2021,"bookKey":"37:1"},"contentVersion":"b4fe814a9121a1a0"},{"id":1037002,"topic":"Equações, inequações e sistemas","sub":"Módulo de um número real","difficulty":"Não classificada","text":"Assinale com V ou F:\n3 x⁰¹. ( ) = 0 ⇒ x = 0 04. ( ) a - b ≥ x + y²\n02. ( ) a . b ≠ a.b⁰⁵. ( ) x = y ⇒ x = y¹⁵ 15 03. ( ) a = a⁰⁶. ( ) x + y ≤ x + y","options":[],"answer":null,"steps":["01 é V: $|3x/2|=0$ obriga $3x/2=0$, logo $x=0$. 02 é F, pois sempre $|a|\\,|b|=|ab|$.","03 é V: ambos os membros representam a décima quinta potência do valor absoluto de a, isto é, $|a|^{15}$.","04 é F: tome $a=b=0$, $x=1$, $y=0$; a afirmação exigiria $0\\ge1$. 05 é F: $x=1$ e $y=-1$ possuem módulos iguais, mas são distintos.","06 é a desigualdade triangular $|x+y|\\le|x|+|y|$, válida para todos os reais: V."],"type":"Discursiva","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"V–F–V–F–F–V","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":40,"number":2,"chapter":"Módulo de um número real","publicationYear":2021,"bookKey":"37:2"},"contentVersion":"335d8687d4c5de4f"},{"id":1037003,"topic":"Equações, inequações e sistemas","sub":"Módulo de um número real","difficulty":"Não classificada","text":"Determine a solução da equação x ² - 3 x - 1 = 3 em ℕ","options":["S = {-1,1,2,4}","S = {1,2,4}","S = {1,2}","NRA"],"answer":1,"steps":["$|x^2-3x-1|=3$ implica $x^2-3x-1=3$ ou $x^2-3x-1=-3$.","A primeira equação é $x^2-3x-4=(x-4)(x+1)=0$, com raízes 4 e −1. A segunda é $x^2-3x+2=(x-1)(x-2)=0$, com raízes 1 e 2.","Restringindo aos naturais, descartamos −1 e ficamos com $S=\\{1,2,4\\}$, alternativa B."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"B — {1, 2, 4}","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":40,"number":3,"chapter":"Módulo de um número real","publicationYear":2021,"bookKey":"37:3"},"contentVersion":"419aca7aeaeff972"},{"id":1037004,"topic":"Equações, inequações e sistemas","sub":"Módulo de um número real","difficulty":"Não classificada","text":"Determine a solução da equação 3 x - 9 - 3 = 6","options":[],"answer":null,"steps":["$|3x-9|-3=6$ equivale a $|3x-9|=9$.","Assim, $3x-9=9$ ou $3x-9=-9$. Resultam $x=6$ e $x=0$. Ambos produzem $9-3=6$ na equação original."],"type":"Discursiva","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"{0, 6}","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":41,"number":4,"chapter":"Módulo de um número real","publicationYear":2021,"bookKey":"37:4"},"contentVersion":"1e3a00f57f213fb5"},{"id":1037005,"topic":"Equações, inequações e sistemas","sub":"Módulo de um número real","difficulty":"Não classificada","text":"Determine a solução da inequação 3 x - 9 - 3 ≤ 1","options":[],"answer":null,"steps":["$|3x-9|-3\\le1$ equivale a $|3x-9|\\le4$.","Pela definição do módulo, $-4\\le3x-9\\le4$. Somando 9: $5\\le3x\\le13$. Dividindo por 3: $5/3\\le x\\le13/3$.","As extremidades são incluídas porque nelas o primeiro membro vale 1. Por exemplo, $x=1$, incluído no gabarito impresso, produz $|3-9|-3=3>1$ e não serve."],"type":"Discursiva","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"O intervalo [1,5] indicado no gabarito impresso não corresponde à inequação original.","answerText":"[5/3, 13/3]","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":41,"number":5,"chapter":"Módulo de um número real","publicationYear":2021,"bookKey":"37:5"},"contentVersion":"ffcfc74862746f7d"},{"id":1037006,"topic":"Equações, inequações e sistemas","sub":"Módulo de um número real","difficulty":"Não classificada","text":"Determine a solução da inequação x + 2 - 8 < 0","options":[],"answer":null,"steps":["$|x+2|-8<0$ equivale a $|x+2|<8$, portanto $-8<x+2<8$.","Subtraindo 2, obtemos $-10<x<6$. Os extremos não entram, pois fariam o primeiro membro igual a zero."],"type":"Discursiva","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"]−10, 6[","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":41,"number":6,"chapter":"Módulo de um número real","publicationYear":2021,"bookKey":"37:6"},"contentVersion":"d67f0c7da9c7013a"},{"id":1037007,"topic":"Equações, inequações e sistemas","sub":"Módulo de um número real","difficulty":"Não classificada","text":"Determine a solução da inequação x² - 2 > 0","options":[],"answer":null,"steps":["Um módulo é sempre não negativo e só deixa de ser estritamente positivo quando seu conteúdo é zero.","Logo $|x^2-2|>0$ equivale a $x^2-2\\ne0$, isto é, $x\\ne-\\sqrt2$ e $x\\ne\\sqrt2$. O conjunto solução é $\\mathbb R\\setminus\\{-\\sqrt2,\\sqrt2\\}$."],"type":"Discursiva","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"O gabarito impresso exclui ±2; a equação original exige excluir ±√2.","answerText":"Todos os reais, exceto −√2 e √2","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":41,"number":7,"chapter":"Módulo de um número real","publicationYear":2021,"bookKey":"37:7"},"contentVersion":"825dc408561f9892"},{"id":1037008,"topic":"Equações, inequações e sistemas","sub":"Módulo de um número real","difficulty":"Não classificada","text":"Determine a solução da inequação x² - 2 - 2 < 0","options":[],"answer":null,"steps":["$|x^2-2|-2<0$ equivale a $|x^2-2|<2$. Assim, $-2<x^2-2<2$.","Somando 2, obtemos $0<x^2<4$. Precisamos de $-2<x<2$ e $x\\ne0$.","Portanto $S=(-2,0)\\cup(0,2)$. Em $x=-2,0,2$, o primeiro membro original é zero, não negativo estrito."],"type":"Discursiva","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"O gabarito impresso inclui zero e os extremos ±2, mas nenhum deles satisfaz a desigualdade estrita.","answerText":"]−2, 0[ ∪ ]0, 2[","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":41,"number":8,"chapter":"Módulo de um número real","publicationYear":2021,"bookKey":"37:8"},"contentVersion":"56781c995c437e35"},{"id":1037009,"topic":"Equações, inequações e sistemas","sub":"Módulo de um número real","difficulty":"Não classificada","text":"Resolver a inequação x - 1 - 3 x + 7 ≤ 0 . Considere U = ℝ","options":[],"answer":null,"steps":["Se $x<1$, então $|x-1|=1-x$ e a inequação vira $8-4x\\le0$, que exigiria $x\\ge2$; não há solução nesse ramo.","Se $x\\ge1$, então $|x-1|=x-1$ e temos $6-2x\\le0$, ou seja, $x\\ge3$.","Reunindo os ramos, $S=[3,+\\infty)$."],"type":"Discursiva","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"[3, +∞[","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":41,"number":9,"chapter":"Módulo de um número real","publicationYear":2021,"bookKey":"37:9"},"contentVersion":"59ba4608d8e16cc6"},{"id":1037010,"topic":"Equações, inequações e sistemas","sub":"Módulo de um número real","difficulty":"Não classificada","text":"Resolver a inequação 2 x + 1 - 3 x + 4 ≥ 0 . Considere U = ℝ","options":[],"answer":null,"steps":["Se $x\\ge-1/2$, então $|2x+1|=2x+1$, logo $5-x\\ge0$. Nesse ramo, $-1/2\\le x\\le5$.","Se $x<-1/2$, então $|2x+1|=-2x-1$, logo $3-5x\\ge0$. Todos os valores desse ramo satisfazem a condição.","A união é $(-\\infty,5]$. Como conferência, $x=0$ dá $1+4\\ge0$, enquanto $x=6$ dá $13-18+4=-1<0$."],"type":"Discursiva","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"O gabarito impresso informa x ≥ 5, mas o sinal da inequação original leva a x ≤ 5.","answerText":"]−∞, 5]","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":41,"number":10,"chapter":"Módulo de um número real","publicationYear":2021,"bookKey":"37:10"},"contentVersion":"623a1a467b2852b3"},{"id":1037011,"topic":"Equações, inequações e sistemas","sub":"Módulo de um número real","difficulty":"Não classificada","text":"Se $\\sqrt{x^2+x+y}=10$ e $x+\\sqrt{y^2-y}=12$, qual é o valor de $x+y$?","options":["$-2$","$2$","$\\frac{18}{5}$","$\\frac23$","$22$"],"answer":2,"steps":["Use $\\sqrt{x^2}=|x|$ e $\\sqrt{y^2}=|y|$. O sistema é $|x|+x+y=10$ e $x+|y|-y=12$.","Se $x<0$, a primeira equação daria $y=10$; a segunda então daria $x=12$, contradição. Portanto $x\\ge0$ e $2x+y=10$.","Se $y\\ge0$, a segunda equação daria $x=12$ e a primeira $y=-14$, contradição. Logo $y<0$ e $x-2y=12$.","Resolvendo $2x+y=10$ e $x-2y=12$, obtemos $x=32/5$, $y=-14/5$. Assim $x+y=18/5$, alternativa C."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"C — 18/5","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":42,"number":11,"chapter":"Módulo de um número real","publicationYear":2021,"bookKey":"37:11"},"contentVersion":"62a9673156591c97"},{"id":1037012,"topic":"Equações, inequações e sistemas","sub":"Módulo de um número real","difficulty":"Não classificada","text":"Sabendo que o sistema possui duas\n\nsoluções (a,b) e (c,d). O valor de a+b+c+d é igual a :","options":["6","7","8","9","10"],"answer":0,"steps":["As equações são $|x|+x+|y|+y=10$ e $|x|-x+|y|-y=4$.","Somando e subtraindo, obtemos $|x|+|y|=7$ e $x+y=3$. Os dois números não podem ter o mesmo sinal, pois nesse caso teríamos soma dos módulos igual a 3 ou soma negativa.","Com sinais opostos, os módulos somam 7 e diferem 3, logo são 5 e 2. As soluções são $(5,-2)$ e $(-2,5)$.","Portanto $a+b+c+d=5-2-2+5=6$, alternativa A."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"A — 6","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":42,"number":12,"chapter":"Módulo de um número real","publicationYear":2021,"bookKey":"37:12"},"contentVersion":"ceab97f256da51ae"},{"id":1037013,"topic":"Equações, inequações e sistemas","sub":"Módulo de um número real","difficulty":"Não classificada","text":"Se 1 < x < 2 , determine o valor de ε, onde ε = x + 2 x - 1 + x - 2 x - 1","options":["-2","0","1","2","4"],"answer":3,"steps":["Defina $t=\\sqrt{x-1}$. Como $1<x<2$, temos $0<t<1$ e $x=t^2+1$.","Os radicandos se tornam $x+2\\sqrt{x-1}=(t+1)^2$ e $x-2\\sqrt{x-1}=(t-1)^2$.","A soma é $|t+1|+|t-1|=(t+1)+(1-t)=2$, alternativa D."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"D — 2","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":42,"number":13,"chapter":"Módulo de um número real","publicationYear":2021,"bookKey":"37:13"},"contentVersion":"d1d6582c98128dc8"},{"id":1037014,"topic":"Equações, inequações e sistemas","sub":"Módulo de um número real","difficulty":"Não classificada","text":"Se a e b são raízes da equação x - 7 + 2 x - 8 = 13 , determine\no valor de a+ b","options":["7","10","13","17","20"],"answer":1,"steps":["Os pontos de mudança de sinal em $|x-7|+|2x-8|=13$ são 4 e 7.","Para $x\\le4$, temos $7-x+8-2x=13$, dando $x=2/3$, válido. Para $4\\le x\\le7$, temos $7-x+2x-8=13$, dando $x=14$, fora do ramo.","Para $x\\ge7$, temos $x-7+2x-8=13$, dando $x=28/3$, válido.","A soma das raízes é $2/3+28/3=10$, alternativa B."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"B — 10","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":42,"number":14,"chapter":"Módulo de um número real","publicationYear":2021,"bookKey":"37:14"},"contentVersion":"4b68ce94229c8978"},{"id":1037015,"topic":"Equações, inequações e sistemas","sub":"Módulo de um número real","difficulty":"Não classificada","text":"Qual a soma de todos os valores de a para os quais a equação\n( x + 3a - 8 ) 2 + ( x - a ) 2 = 4 possui infinitas soluções?","options":["4","5","6","7","8"],"answer":0,"steps":["A equação é $|x-(8-3a)|+|x-a|=4$. Ela representa a soma das distâncias de x aos pontos $8-3a$ e a.","Entre dois pontos distintos, essa soma é constante e igual à distância entre eles. Há infinitas soluções exatamente quando $|(8-3a)-a|=4$.","Logo $|8-4a|=4$, o que dá $a=1$ ou $a=3$. Em ambos os casos, todo o intervalo entre os pontos resolve a equação.","Se a distância fosse menor que 4, haveria somente duas soluções externas; se maior, nenhuma. A soma dos parâmetros admissíveis é $1+3=4$."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"A — 4","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":42,"number":15,"chapter":"Módulo de um número real","publicationYear":2021,"bookKey":"37:15"},"contentVersion":"364bcfd2efd9dd2f"},{"id":1037016,"topic":"Equações, inequações e sistemas","sub":"Módulo de um número real","difficulty":"Não classificada","text":"Resolva a inequação 3 ≤ (1 - x ) 2 ≤ 4 .\n\n2","options":[],"answer":null,"steps":["$\\sqrt{(1-x)^2}=|1-x|=|x-1|$. Portanto $3\\le|x-1|\\le4$.","Isso significa $x-1\\in[-4,-3]\\cup[3,4]$. Somando 1, $x\\in[-3,-2]\\cup[4,5]$."],"type":"Discursiva","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"[−3, −2] ∪ [4, 5]","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":43,"number":16,"chapter":"Módulo de um número real","publicationYear":2021,"bookKey":"37:16"},"contentVersion":"d39ec76065d882f4"},{"id":1037017,"topic":"Equações, inequações e sistemas","sub":"Módulo de um número real","difficulty":"Não classificada","text":"A soma das raízes da equação x + 2 2 - x + 2 - 2 = 0 vale:","options":["-8","-4","0","4","1"],"answer":1,"steps":["Defina $t=|x+2|\\ge0$. A equação passa a ser $t^2-t-2=(t-2)(t+1)=0$.","A raiz $t=-1$ é impossível. Então $|x+2|=2$, dando $x=0$ ou $x=-4$.","A soma é $0-4=-4$, alternativa B."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"B — −4","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":43,"number":17,"chapter":"Módulo de um número real","publicationYear":2021,"bookKey":"37:17"},"contentVersion":"12fe079d987bbbea"},{"id":1037018,"topic":"Equações, inequações e sistemas","sub":"Módulo de um número real","difficulty":"Não classificada","text":"Determine o número de valores inteiros de x que satisfazem à\ninequação x² + ( 2 x - 6 ) 2 ≤ ( x + 6 ) 2","options":["3","4","5","6","7"],"answer":4,"steps":["A inequação equivale a $|x|+|2x-6|\\le|x+6|$. Os pontos críticos são −6, 0 e 3.","Para $x<-6$, fica $-3x+6\\le-x-6$, exigindo $x\\ge6$, impossível. Para $-6\\le x<0$, fica $-3x+6\\le x+6$, exigindo $x\\ge0$, também impossível nesse intervalo.","Para $0\\le x\\le3$, fica $6-x\\le x+6$, sempre verdadeira. Para $x\\ge3$, fica $3x-6\\le x+6$, ou seja, $x\\le6$.","A solução real é $[0,6]$. Os inteiros são 0, 1, 2, 3, 4, 5 e 6: sete valores, alternativa E."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"E — 7 inteiros","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":43,"number":18,"chapter":"Módulo de um número real","publicationYear":2021,"bookKey":"37:18"},"contentVersion":"aa687b24fb8b777b"},{"id":1037019,"topic":"Equações, inequações e sistemas","sub":"Módulo de um número real","difficulty":"Não classificada","text":"Se x < 1 , então 4 + x + ( x - 1) 2 é igual a:","options":["3","5","2 x + 3","2 x + 5","-2 x - 3"],"answer":1,"steps":["Como $x<1$, temos $x-1<0$ e $\\sqrt{(x-1)^2}=|x-1|=1-x$.","Substituindo: $4+x+(1-x)=5$. Alternativa B."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"B — 5","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":43,"number":19,"chapter":"Módulo de um número real","publicationYear":2021,"bookKey":"37:19"},"contentVersion":"567af20d6c118440"},{"id":1037020,"topic":"Equações, inequações e sistemas","sub":"Módulo de um número real","difficulty":"Não classificada","text":"Se 1r e 2r são raízes reais distintas de x² + px + 8 = 0 , é correto\nafirmar que:","options":["r1 + r2 > 4 2","r1 + r2 < 2","r1 ≥ 2 e r2 ≥ 2","r1 ≥ 3 e r2 ≤ 1","r1 <1 e r2 < 2"],"answer":0,"steps":["Para $x^2+px+8=0$ possuir raízes reais distintas, o discriminante deve satisfazer $p^2-32>0$.","Portanto $|p|>\\sqrt{32}=4\\sqrt2$. Pelas relações de Viète, $r_1+r_2=-p$.","Assim $|r_1+r_2|=|p|>4\\sqrt2$, exatamente a alternativa A."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"A","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":43,"number":20,"chapter":"Módulo de um número real","publicationYear":2021,"bookKey":"37:20"},"contentVersion":"d58c0866a2391c49"},{"id":1037021,"topic":"Equações, inequações e sistemas","sub":"Módulo de um número real","difficulty":"Não classificada","text":"Dada a equação 2 x - 3 + x - 5 = 0 , a soma de todas as suas\n\nsoluções é igual a:","options":["3","8/3","2","4/3","2/3"],"answer":2,"steps":["Em $|2x-3|+|x|=5$, os pontos críticos são 0 e $3/2$.","Para $x<0$, temos $3-2x-x=5$, dando $x=-2/3$. Para $0\\le x\\le3/2$, temos $3-2x+x=5$, dando $x=-2$, fora do ramo.","Para $x\\ge3/2$, temos $2x-3+x=5$, dando $x=8/3$. A soma é $-2/3+8/3=2$, alternativa C."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"C — 2","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":43,"number":21,"chapter":"Módulo de um número real","publicationYear":2021,"bookKey":"37:21"},"contentVersion":"531f76d8e21752bd"},{"id":1037022,"topic":"Equações, inequações e sistemas","sub":"Módulo de um número real","difficulty":"Não classificada","text":"A soma dos quadrados de todas as raízes da equação\nx² + 4 x - 2. x + 2 + 4 = 0 é igual a","options":["16","20","24","28","36"],"answer":1,"steps":["Reescreva $x^2+4x-2|x+2|+4=0$ como $(x+2)^2-2|x+2|=0$.","Com $t=|x+2|\\ge0$, temos $t^2-2t=t(t-2)=0$. Se $t=0$, $x=-2$; se $t=2$, $x=0$ ou $x=-4$.","A soma dos quadrados das três raízes distintas é $(-2)^2+0^2+(-4)^2=4+16=20$, alternativa B."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"B — 20","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":44,"number":22,"chapter":"Módulo de um número real","publicationYear":2021,"bookKey":"37:22"},"contentVersion":"8aa719114b4ea4ae"},{"id":1037023,"topic":"Equações, inequações e sistemas","sub":"Módulo de um número real","difficulty":"Não classificada","text":"Resolva a equação x + 1 - x + 3 x - 1 - 2 x - 2 = x + 2 .\n\n2 1","options":[],"answer":null,"steps":["Os pontos críticos de $|x+1|-|x|+3|x-1|-2|x-2|=x+2$ são −1, 0, 1 e 2.","Para $x<-1$, o primeiro membro é $-x-2$, dando $x=-2$. Para $-1\\le x<0$, ele é x, tornando impossível $x=x+2$.","Para $0\\le x<1$, ele é $-x$, dando $x=-1$, fora do ramo. Para $1\\le x<2$, ele é $5x-6$, dando $x=2$, que é o extremo seguinte.","Para $x\\ge2$, o primeiro membro é identicamente $x+2$; todos esses números servem. Logo $S=\\{-2\\}\\cup[2,+\\infty)$."],"type":"Discursiva","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"{−2} ∪ [2, +∞[","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":44,"number":23,"chapter":"Módulo de um número real","publicationYear":2021,"bookKey":"37:23"},"contentVersion":"44abc280b29f762c"},{"id":1037024,"topic":"Equações, inequações e sistemas","sub":"Módulo de um número real","difficulty":"Não classificada","text":"Qual é o conjunto-solução de $\\left|\\frac{2x+1}{x-3}\\right|>3$?","options":["]$\\frac85,3$[ $\\cup$ ]$3,+\\infty$[","]$3,10$[ $\\cup$ ]$10,+\\infty$[","]$-\\infty,\\frac85$[ $\\cup$ ]$3,10$[","]$\\frac85,3$[ $\\cup$ ]$3,10$[","]$\\frac85,3$[ $\\cup$ ]$10,+\\infty$["],"answer":3,"steps":["O domínio exige $x\\ne3$. A desigualdade $|(2x+1)/(x-3)|>3$ equivale à união dos casos $(2x+1)/(x-3)>3$ e $(2x+1)/(x-3)<-3$.","No primeiro caso, $(10-x)/(x-3)>0$, cuja solução é $3<x<10$.","No segundo, $(5x-8)/(x-3)<0$, cuja solução é $8/5<x<3$.","Reunindo, $S=(8/5,3)\\cup(3,10)$. As extremidades $8/5$ e 10 dão módulo 3 e não entram. Alternativa D."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"D — ]8/5, 3[ ∪ ]3, 10[","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":44,"number":24,"chapter":"Módulo de um número real","publicationYear":2021,"bookKey":"37:24"},"contentVersion":"7e6aaac372f3353d"},{"id":1037025,"topic":"Equações, inequações e sistemas","sub":"Módulo de um número real","difficulty":"Não classificada","text":"2\nx - x² ( )25) Se x < 0 , então é igual a:\nx","options":["-2","-1","0","1","2"],"answer":0,"steps":["Como $x<0$, $\\sqrt{x^2}=|x|=-x$. Portanto $x-\\sqrt{x^2}=2x$.","O numerador é $\\sqrt{(2x)^2}=|2x|=-2x$. Dividindo por $x\\ne0$, o resultado é −2: alternativa A."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"A — −2","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":44,"number":25,"chapter":"Módulo de um número real","publicationYear":2021,"bookKey":"37:25"},"contentVersion":"ee9d801bfa099eeb"},{"id":1037026,"topic":"Equações, inequações e sistemas","sub":"Módulo de um número real","difficulty":"Não classificada","text":"Se x e y são reais e ( x + y - 17 ) 2 + ( x - y - 5 ) 2 = 0 ,\ndetermine o algarismo das dezenas simples do número yx","options":["2","3","4","5","6"],"answer":4,"steps":["A soma de dois módulos não negativos só pode ser zero se ambos forem zero. Logo $x+y-17=0$ e $x-y-5=0$.","Somando as equações, $2x=22$, então $x=11$ e $y=6$. O número pedido é $x^y=11^6$.","Pelo binômio, $(1+10)^6\\equiv1+6\\cdot10=61\\pmod{100}$, pois os termos de grau pelo menos dois são múltiplos de 100.","Os dois últimos algarismos são 61; o algarismo das dezenas é 6, alternativa E."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"E — 6","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":44,"number":26,"chapter":"Módulo de um número real","publicationYear":2021,"bookKey":"37:26"},"contentVersion":"fd4ccd2cbe41fe11"},{"id":1037027,"topic":"Equações, inequações e sistemas","sub":"Módulo de um número real","difficulty":"Não classificada","text":"Determine a soma das raízes positivas da equação 2 - 1 - x = 1","options":["2","4","6","8","10"],"answer":2,"steps":["Defina $t=|x|\\ge0$. A equação $|2-|1-|x|||=1$ vira $|2-|1-t||=1$.","Assim $|1-t|=1$ ou $|1-t|=3$. O primeiro caso dá $t=0$ ou 2; o segundo dá $t=-2$ ou 4, mas −2 é impossível.","Portanto $|x|\\in\\{0,2,4\\}$ e as raízes são $0,\\pm2,\\pm4$. As positivas são 2 e 4; sua soma é 6, alternativa C."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"C — 6","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":44,"number":27,"chapter":"Módulo de um número real","publicationYear":2021,"bookKey":"37:27"},"contentVersion":"24cfc5a822a5dd75"},{"id":1037028,"topic":"Equações, inequações e sistemas","sub":"Módulo de um número real","difficulty":"Não classificada","text":"Sejam x e y números reais quaisquer. Assinale a afirmação\n\ncorreta:\nx + y x - y","options":["x + y ≤","x - y ≥\n2 2","x + y > x² + y²","xy > x . y","x + y = 2 x² + y²"],"answer":1,"steps":["A desigualdade triangular reversa garante $|x-y|\\ge\\big||x|-|y|\\big|$. Como esse último membro é não negativo, também é maior ou igual à sua metade; portanto B é verdadeira.","A é refutada por $x=y=1$: $2\\nleq1$. C é refutada por $x=y=0$. D é falsa porque sempre $|xy|=|x|\\,|y|$. E é refutada por $x=1,y=0$: $1\\ne2$."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"B","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":45,"number":28,"chapter":"Módulo de um número real","publicationYear":2021,"bookKey":"37:28"},"contentVersion":"7b758f8189a8a853"},{"id":1037029,"topic":"Equações, inequações e sistemas","sub":"Módulo de um número real","difficulty":"Não classificada","text":"A intersecção dos conjuntos { x ∈ ℝ / x - 2 ≤ 4} e\n{ x ∈ ℝ / x - 7 ≤ 2} é um intervalo de comprimento","options":["2","5","1","3","4"],"answer":2,"steps":["$|x-2|\\le4$ equivale a $-2\\le x\\le6$. Já $|x-7|\\le2$ equivale a $5\\le x\\le9$.","A interseção é o intervalo $[5,6]$, cujo comprimento é $6-5=1$. Alternativa C."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"C — comprimento 1","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":45,"number":29,"chapter":"Módulo de um número real","publicationYear":2021,"bookKey":"37:29"},"contentVersion":"8ca29f1ac422f524"},{"id":1037030,"topic":"Equações, inequações e sistemas","sub":"Módulo de um número real","difficulty":"Não classificada","text":"Qualquer que seja o número real não nulo x , tem-se sempre:\n1 1 1(","options":["x + ≥ 2","x + ≤ 10","x + ≤ x x x x¹ 1","x + <","nenhuma das anteriores\nx x"],"answer":0,"steps":["Para $x\\ne0$, os números x e $1/x$ têm o mesmo sinal. Assim $|x+1/x|=|x|+1/|x|$.","Escreva $t=|x|>0$. De $(t-1)^2\\ge0$, obtemos $t^2+1\\ge2t$ e, dividindo por t, $t+1/t\\ge2$.","Logo $|x+1/x|\\ge2$ para todo real não nulo. A igualdade ocorre em $x=1$ ou $x=-1$. Alternativa A."],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Texto","solutionNote":"","answerText":"A","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":45,"number":30,"chapter":"Módulo de um número real","publicationYear":2021,"bookKey":"37:30"},"contentVersion":"4c8bb8b437857fd4"},{"id":1048001,"topic":"Polinômios","sub":"Operações com polinômios","difficulty":"Não classificada","text":"Determine o grau do polinômio p ( x ) = ( x - 2 )( 2 x - 3 )( x + 5 )","options":[],"answer":null,"steps":[],"type":"Discursiva","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Pendente","solutionNote":"","answerText":"","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":64,"number":1,"chapter":"Polinômios","publicationYear":2021,"bookKey":"48:1"},"contentVersion":"ce44d4fe8ef54c19"},{"id":1048002,"topic":"Polinômios","sub":"Operações com polinômios","difficulty":"Não classificada","text":"Sabendo que os polinômios p ( x ) = ax 3 - 5 x² + x + b e\nq ( x ) = 6 x³ + cx 2 + x + 7 são idênticos, determine o valor de a + b + c","options":[],"answer":null,"steps":[],"type":"Discursiva","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Pendente","solutionNote":"","answerText":"","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":64,"number":2,"chapter":"Polinômios","publicationYear":2021,"bookKey":"48:2"},"contentVersion":"63d2a3968807dec6"},{"id":1048003,"topic":"Polinômios","sub":"Operações com polinômios","difficulty":"Não classificada","text":"Qual o valor numérico do polinômio p ( x ) = -2 x⁵ + 4 x⁴ + 3 x³ + 2 x - 8\npara x = -1 ?","options":[],"answer":null,"steps":[],"type":"Discursiva","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Pendente","solutionNote":"","answerText":"","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":64,"number":3,"chapter":"Polinômios","publicationYear":2021,"bookKey":"48:3"},"contentVersion":"ed73b47c3b563b5f"},{"id":1048004,"topic":"Polinômios","sub":"Operações com polinômios","difficulty":"Não classificada","text":"A soma de dois polinômios p ( x ) + q ( x ) = - x³ + 2 x³ + x² + 11x - 3 e que\np ( x ) = x⁵ - 2 x³ + 10 x - 5 , determine q ( x )","options":[],"answer":null,"steps":[],"type":"Discursiva","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Pendente","solutionNote":"","answerText":"","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":64,"number":4,"chapter":"Polinômios","publicationYear":2021,"bookKey":"48:4"},"contentVersion":"21b89431a9b76e10"},{"id":1048005,"topic":"Polinômios","sub":"Operações com polinômios","difficulty":"Não classif