nte","solutionNote":"","answerText":"","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":386,"number":98,"chapter":"Miscelânea de questões","publicationYear":2021,"bookKey":"360:98"},"contentVersion":"f47ca46b0dad41eb"},{"id":1360099,"topic":"Álgebra e expressões algébricas","sub":"Problemas de álgebra","difficulty":"Não classificada","text":"Sendo a um número real positivo, sobre as raízes reais da equação\nx ( x - a )( x + a )( x + 2 a ) = 3a 4 , podemos afirmar que:","options":["a soma das raízes é um número racional positivo","a soma das raízes é um número real positivo","o produto das raízes é um número real positivo","o produto das raízes é um número inteiro negativo","a soma das raízes pode ser um número inteiro negativo\n\nDica: Multiplique o primeiro fator pelo terceiro e o segundo pelo\n\nquarto.\nAdotar 2x + ax = a resolver a eq. do segundo grau em α"],"answer":null,"steps":[],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Pendente","solutionNote":"","answerText":"","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":386,"number":99,"chapter":"Miscelânea de questões","publicationYear":2021,"bookKey":"360:99"},"contentVersion":"ddd8677d3f1e09e1"},{"id":1360100,"topic":"Álgebra e expressões algébricas","sub":"Problemas de álgebra","difficulty":"Não classificada","text":"Se então\n\n2 4 1 é igual a :x + x - 1 +\nx² + x⁴ - 1","options":["5,05","20","51,005","61,25","400"],"answer":null,"steps":[],"type":"Múltipla escolha","institution":"Tópicos de Álgebra Elementar","exam":"Tópicos de Álgebra Elementar","year":null,"solution":"Pendente","solutionNote":"","answerText":"","bookOriginal":true,"transcribed":true,"source":{"name":"Tópicos de Álgebra Elementar","page":386,"number":100,"chapter":"Miscelânea de questões","publicationYear":2021,"bookKey":"360:100"},"contentVersion":"9019e8db8ce59ade"}]$tae_payload$::jsonb)
  ), upserted AS (
    INSERT INTO public.questoes AS existing
      (id, enunciado, alternativas, gabarito, assunto, subassunto, instituicao,
       ano, dificuldade, figura_url, resolucao, fonte, dados_aplicacao, resumo_aplicacao)
    SELECT (item->>'id')::bigint, item->>'text', item->'options',
      (item->>'answer')::integer, item->>'topic', item->>'sub', item->>'institution',
      (item->>'year')::integer,
      CASE WHEN item->>'difficulty' IN ('Fácil','Média','Difícil')
        THEN lower(item->>'difficulty') ELSE NULL END,
      item->'figure'->>'src',
      (SELECT string_agg(step, E'\n\n' ORDER BY n)
       FROM jsonb_array_elements_text(item->'steps') WITH ORDINALITY AS s(step,n)),
      item->'source'->>'name', item,
      item - ARRAY['text','steps','answerText','solutionNote','figure']::text[]
    FROM incoming
    ON CONFLICT (id) DO UPDATE SET
      enunciado=EXCLUDED.enunciado, alternativas=EXCLUDED.alternativas,
      gabarito=EXCLUDED.gabarito, assunto=EXCLUDED.assunto,
      subassunto=EXCLUDED.subassunto, instituicao=EXCLUDED.instituicao,
      ano=EXCLUDED.ano, dificuldade=EXCLUDED.dificuldade,
      figura_url=EXCLUDED.figura_url, resolucao=EXCLUDED.resolucao,
      fonte=EXCLUDED.fonte, dados_aplicacao=EXCLUDED.dados_aplicacao,
      resumo_aplicacao=EXCLUDED.resumo_aplicacao,
      updated_at=now()
    WHERE existing.fonte=EXCLUDED.fonte
    RETURNING 1
  )
  SELECT count(*) INTO imported FROM upserted;
  IF imported <> 712 THEN
    RAISE EXCEPTION 'Expected 712 original exercises, imported %. An ID belongs to another source; no changes were committed.', imported;
  END IF;
END $tae_import$;
COMMIT;
